package main

import (
	"fmt"
	"log"
)

func Calculate(val int) (int, error) {
	if val < 0 {
		return 0, fmt.Errorf("invalid value: %d", val)
	}
	return val * 2, nil
}

func main() {
	result, err := Calculate(5)
	if err != nil {
		log.Fatal(err)
	}
	fmt.Println(result)
}
